parameters.query:
=SELECT
  payment_type AS metodo,
  payment_amount * -1 AS monto
FROM miconsul_uno.ospos_sale_payments
WHERE sale_id = {{$('MySQL: Datos de la Venta').item.json.sale_id}}
ORDER BY payment_id ASC;

