// Log de resultado
const emailSent = $('Enviar Email: Ticket').all().length > 0;
const waSent    = $('Enviar WhatsApp: YCloud').all().length > 0;
const sale      = $('Code: Construir Ticket').first().json;

console.log(`[TICKET] Venta #${sale.sale_id} - ${sale.paciente_nombre}`);
console.log(`[TICKET] Email: ${emailSent ? '✅ Enviado' : '⚠️ Sin email'}`);
console.log(`[TICKET] WhatsApp: ${waSent ? '✅ Enviado' : '⚠️ Sin teléfono'}`);

return [{
  json: {
    sale_id:    sale.sale_id,
    paciente:   sale.paciente_nombre,
    email_ok:   emailSent,
    wa_ok:      waSent,
    timestamp:  new Date().toISOString(),
    status:     'completed'
  }
}];
